// Hand-written list of canonical ingredients for meal prep. build-catalog.ts
// resolves each `usda` query against the USDA FoodData Central extract (an
// exact description wins; otherwise every word must appear, SR Legacy first,
// shortest description first) and writes server/meal-prep/food/data/
// ingredients.json with the chosen food's id, description, macros and
// household portions, for review in git.
//
// Row: [id, name, aisle, usda query | null, aliases ("|"-separated), opts]
//   opts.a      allergens: dairy, egg, gluten, soy, sesame, tree-nut, peanut, fish, shellfish
//   opts.p      main-protein kind when this is the star of a dish
//   opts.piece  grams for "1" of it when USDA has no whole-item portion
//   opts.cup    grams per US cup when USDA has none (sets density)
//   opts.can    grams in the usual can/jar/package when a line says "1 can"
//   opts.m      manual macros per 100 g [kcal, protein, carbs, fat, fiber] (label data; no USDA match)
//   opts.cooked true when USDA values are for the cooked food
//   opts.por    grams per portion (clove, head, stalk...), overriding USDA's
import type { Aisle } from "../../shared/meal-prep/contract";
import type { PortionKey } from "../../server/meal-prep/food/units";

export interface SpecOpts {
  a?: string[];
  p?: string;
  piece?: number;
  cup?: number;
  can?: number;
  m?: [number, number, number, number, number?];
  cooked?: boolean;
  /** grams per household portion, overriding USDA's */
  por?: Partial<Record<PortionKey, number>>;
}
export type SpecRow = [string, string, Aisle, string | null, string, SpecOpts?];

const P: Aisle = "Produce", M: Aisle = "Meat & Seafood", D: Aisle = "Dairy & Eggs", B: Aisle = "Bakery",
  PA: Aisle = "Pantry", C: Aisle = "Canned & Jarred", G: Aisle = "Pasta, Rice & Grains", BK: Aisle = "Baking",
  S: Aisle = "Spices & Seasonings", O: Aisle = "Oils, Vinegars & Condiments", F: Aisle = "Frozen",
  BV: Aisle = "Beverages", SN: Aisle = "Snacks", OT: Aisle = "Other";

const dairy = { a: ["dairy"] }, egg = { a: ["egg"] }, gluten = { a: ["gluten"] }, soy = { a: ["soy"] },
  nut = { a: ["tree-nut"] }, fish = { a: ["fish"], p: "fish" }, shell = { a: ["shellfish"], p: "shellfish" };

